  { id = "REDSHARD", n = 72, slug = "red-shard", name = "Red Shard", category = "collectibles", attributes = { "underground" }, flingPower = 30, shortEffect = "No effect. Can be traded for items or moves.", effect = "No effect. In Diamond and Pearl, trade ten for a Sunny Day TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for a Cheri Berry, a Leppa Berry, and a Pecha Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Persim Berry, a Pomeg Berry, and a Razz Berry with the Juggler near the Pal Park entrance in Fuchsia City." },
  { id = "BLUESHARD", n = 73, slug = "blue-shard", name = "Blue Shard", category = "collectibles", attributes = { "underground" }, flingPower = 30, shortEffect = "No effect. Can be traded for items or moves.", effect = "No effect. In Diamond and Pearl, trade ten for a Rain Dance TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for a Chesto Berry, an Oran Berry, and a Wiki Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Bluk Berry, a Cornn Berry, and a Kelpsy Berry with the Juggler near the Pal Park entrance in Fuchsia City." },
