  { id = "GREENSHARD", n = 75, slug = "green-shard", name = "Green Shard", category = "collectibles", attributes = { "underground" }, flingPower = 30, shortEffect = "No effect. Can be traded for items or moves.", effect = "No effect. In Diamond and Pearl, trade ten for a Hail TM in the house midway along the southern section of Route 212. In Platinum, trade to move tutors on Route 212, in Snowpoint City, and in the Survival Area. Eight shards total are required per tutelage, but the particular combination of colors varies by move. In HeartGold and SoulSilver, trade one for an Aguav Berry, a Lum Berry, and a Rawst Berry with the Juggler near the Pokémon Center in Violet City. In HeartGold and SoulSilver, trade one for a Durin Berry, a Hondew Berry, and a Wepear Berry with the Juggler near the Pal Park entrance in Fuchsia City." },
  { id = "SUPERREPEL", n = 76, slug = "super-repel", name = "Super Repel", category = "spelunking", flingPower = 30, shortEffect = "For 200 steps, prevents wild encounters of level lower than your party’s lead Pokémon.", effect = "Used outside of battle : Trainer will skip encounters with wild Pokémon of a lower level than the lead party Pokémon. This effect wears off after the trainer takes 200 steps." },
