  { id = "HONEY", n = 94, slug = "honey", name = "Honey", category = "dex-completion", flingPower = 30, shortEffect = "", effect = "Used outside of battle : Immediately triggers a wild Pokémon battle, as long as the trainer is somewhere with wild Pokémon—i.e., in tall grass, in a cave, or surfing. Can be smeared on sweet-smelling trees to attract tree-dwelling Pokémon after six hours." },
