  { id = "LANSATBERRY", n = 183, slug = "lansat-berry", name = "Lansat Berry", category = "in-a-pinch", attributes = { "holdable-active" }, flingPower = 10, flingEffect = "berry-effect", shortEffect = "Held: Consumed at 1/4 max HP to boost critical hit ratio by two stages.", effect = "Held in battle : When the holder has 1/4 its max HP remaining or less, it consumes this item to raise its critical hit chance by one stage." },
  { id = "STARFBERRY", n = 184, slug = "starf-berry", name = "Starf Berry", category = "in-a-pinch", attributes = { "holdable-active" }, flingPower = 10, flingEffect = "berry-effect", shortEffect = "Held: Consumed at 1/4 max HP to boost a random stat by two stages.", effect = "Held in battle : When the holder has 1/4 its max HP remaining or less, it consumes this item to raise a random stat by two stages." },
  { id = "ENIGMABERRY", n = 185, slug = "enigma-berry", name = "Enigma Berry", category = "other", attributes = { "holdable-active" }, flingPower = 10, shortEffect = "Held: Consumed when struck by a super-effective attack to restore 1/4 max HP.", effect = "Held in battle : When the holder takes super-effective damage, it consumes this item to restore 1/4 its max HP." },
  { id = "MICLEBERRY", n = 186, slug = "micle-berry", name = "Micle Berry", category = "in-a-pinch", attributes = { "holdable-active" }, flingPower = 10, flingEffect = "berry-effect", shortEffect = "Held: Consumed at 1/4 max HP to boost accuracy of next move by 20%. (Gen IV: Perfect accuracy)", effect = "Held in battle : When the holder has 1/4 its max HP remaining or less, it consumes this item, and its next used move has 1.2× its normal accuracy." },
  { id = "CUSTAPBERRY", n = 187, slug = "custap-berry", name = "Custap Berry", category = "in-a-pinch", attributes = { "holdable-active" }, flingPower = 10, shortEffect = "Held: Consumed at 1/4 max HP when using a move to go first.", effect = "Held in battle : When the holder has 1/4 its max HP remaining or less, it consumes this item. On the following turn, the holder will act first among moves with the same priority, regardless of Speed." },
  { id = "JABOCABERRY", n = 188, slug = "jaboca-berry", name = "Jaboca Berry", category = "other", attributes = { "holdable-active" }, flingPower = 10, shortEffect = "Held: Consumed to deal 1/8 attacker’s max HP when holder is struck by a physical attack.", effect = "Held in battle : When the holder takes physical damage, it consumes this item to damage the attacking Pokémon for 1/8 its max HP." },
  { id = "ROWAPBERRY", n = 189, slug = "rowap-berry", name = "Rowap Berry", category = "other", attributes = { "holdable-active" }, flingPower = 10, shortEffect = "Held: Consumed to deal 1/8 attacker’s max HP when holder is struck by a special attack.", effect = "Held in battle : When the holder takes special damage, it consumes this item to damage the attacking Pokémon for 1/8 its max HP." },
  { id = "BRIGHTPOWDER", n = 190, slug = "bright-powder", name = "Bright Powder", category = "held-items", attributes = { "holdable", "holdable-active" }, flingPower = 10, shortEffect = "Held: Increases the holder’s evasion by 1/9 (11 1/9%).", effect = "Held in battle : Moves targeting the holder have 0.9× chance to hit." },
  { id = "WHITEHERB", n = 191, slug = "white-herb", name = "White Herb", category = "held-items", attributes = { "holdable", "holdable-active" }, flingPower = 10, flingEffect = "herb-effect", shortEffect = "Held: Resets all lowered stats to normal at end of turn. Consumed after use.", effect = "Held in battle : At the end of each turn, if any of the holder’s stats have a negative stat modifier, the holder consumes this item to remove the modifiers from those stats." },
  { id = "MACHOBRACE", n = 192, slug = "macho-brace", name = "Macho Brace", category = "effort-training", attributes = { "holdable", "holdable-active" }, flingPower = 60, shortEffect = "Held: Holder gains double effort values from battles, but has halved Speed in battle.", effect = "Held : When the holder would gain effort due to battle, it gains double that effort instead. Held in battle : Holder has half its Speed." },
  { id = "EXPSHARE", n = 193, slug = "exp-share", name = "Exp. Share", category = "training", attributes = { "holdable", "holdable-active" }, shortEffect = "Held: Half the experience from a battle is split between Pokémon holding this item.", effect = "Held : Experience is split across two groups: Pokémon who participated in battle, and Pokémon holding this item. Each Pokémon earns experience as though it had battled alone, divided by the number of Pokémon in its group, then divided by the number of groups. Pokémon holding this item who also participated in battle effectively earn experience twice. Fainted Pokémon never earn experience, and empty groups are ignored; thus, if a single Pokémon is holding this item and the only Pokémon who battled faints from Explosion, the holder will gain full experience." },
  { id = "QUICKCLAW", n = 194, slug = "quick-claw", name = "Quick Claw", category = "held-items", attributes = { "holdable", "holdable-active" }, flingPower = 80, shortEffect = "Held: Holder has a 3/16 (18.75%) chance to move first.", effect = "Held in battle : Whenever the holder attempts to use a move, it has a 3/16 chance to act first among moves with the same priority. If multiple Pokémon have this effect at the same time, Speed is the tie-breaker as normal, but the effect of Trick Room is ignored." },
  { id = "SOOTHEBELL", n = 195, slug = "soothe-bell", name = "Soothe Bell", category = "training", attributes = { "holdable", "holdable-active" }, flingPower = 10, shortEffect = "Held: Doubles the happiness earned by the holder.", effect = "Held : When the holder would earn happiness for any reason, it earns twice that amount instead." },
  { id = "MENTALHERB", n = 196, slug = "mental-herb", name = "Mental Herb", category = "held-items", attributes = { "holdable", "holdable-active" }, flingPower = 10, flingEffect = "herb-effect", shortEffect = "Held: Consumed to cure infatuation. Gen V: Also removes Taunt, Encore, Torment, Disable, and Cursed Body.", effect = "Held in battle : When the holder is attracted, it consumes this item to cure the attraction." },
  { id = "CHOICEBAND", n = 197, slug = "choice-band", name = "Choice Band", category = "choice", attributes = { "holdable", "holdable-active" }, flingPower = 10, shortEffect = "Held: Increases Attack by 50%, but restricts the holder to only one move.", effect = "Held in battle : Holder has 1.5× its Attack. When the holder attempts to use a move, all its other moves are disabled until it leaves battle or loses this item. The restriction ends even if this item is swapped for another Choice item via Trick or Switcheroo." },
  { id = "KINGSROCK", n = 198, slug = "kings-rock", name = "King’s Rock", category = "held-items", attributes = { "holdable", "holdable-active" }, flingPower = 30, flingEffect = "flinch", shortEffect = "Held: Damaging moves gain a 10% chance to make their target flinch. Traded on a Poliwhirl: Holder evolves into Politoed. Traded on a Slowpoke: Holder evolves into Slowking.", effect = "Held in battle : Holder’s damaging moves have a 10% chance to make their target flinch. This chance applies independently to each hit of a multi-hit move. This item’s chance is rolled independently of any other move effects; e.g., a move with a 30% chance to flinch normally will have a 37% total chance to flinch when used with this item, because 3% of the time, both effects activate. Held by Poliwhirl or Slowbro : Holder evolves into Politoed or Slowking, respectively, when traded." },
  { id = "SILVERPOWDER", n = 199, slug = "silver-powder", name = "Silver Powder", category = "type-enhancement", attributes = { "holdable", "holdable-active" }, flingPower = 10, shortEffect = "Held: Bug-Type moves from holder do 20% more damage.", effect = "Held in battle : Holder’s Bug-type moves have 1.2× their power." },
  { id = "AMULETCOIN", n = 200, slug = "amulet-coin", name = "Amulet Coin", category = "training", attributes = { "holdable", "holdable-active" }, flingPower = 30, shortEffect = "Held: Doubles the money earned from a battle. Does not stack with Luck Incense.", effect = "Held : If the holder participated in a trainer battle, the trainer earns twice the usual prize money. This effect applies even if the holder fainted. This effect does not stack with any other similar effect." },
  { id = "CLEANSETAG", n = 201, slug = "cleanse-tag", name = "Cleanse Tag", category = "training", attributes = { "holdable" }, flingPower = 30, shortEffect = "Prevents wild encounters of level lower than your party’s lead Pokémon.", effect = "Held by lead Pokémon: Prevents wild battles with Pokémon that are lower level than the holder." },
  { id = "SOULDEW", n = 202, slug = "soul-dew", name = "Soul Dew", category = "species-specific", attributes = { "holdable" }, flingPower = 30, shortEffect = "Raises Latias and Latios’s Special Attack and Special Defense by 50%.", effect = "Held by Latias or Latios: Increases the holder’s Special Attack and Special Defense by 50%." },
