  { id = "IRONBALL", n = 255, slug = "iron-ball", name = "Iron Ball", category = "bad-held-items", attributes = { "holdable", "holdable-active", "underground" }, flingPower = 130, shortEffect = "Held: Holder’s Speed is halved. Negates all Ground-type immunities, and makes Flying-types take neutral damage from Ground-type moves. Arena Trap. Spikes, and Toxic Spikes affect the holder.", effect = "Held: Decreases the holder’s Speed by 50%. If the holder is Flying or has Levitate, it takes regular damage from Ground attacks and is suspectible to Spikes and Toxic Spikes." },
  { id = "LAGGINGTAIL", n = 256, slug = "lagging-tail", name = "Lagging Tail", category = "bad-held-items", attributes = { "holdable", "holdable-active" }, flingPower = 10, shortEffect = "Held: Holder moves last in its priority bracket.", effect = "Held: The holder will go last within its move’s priority bracket, regardless of Speed. If multiple Pokémon within the same priority bracket are subject to this effect, the slower Pokémon will go first. The holder will move after Pokémon with Stall. If the holder has Stall, Stall is ignored. This item ignores Trick Room." },
