  { id = "GOODROD", n = 423, slug = "good-rod", name = "Good Rod", category = "gameplay", shortEffect = "Used to catch Pokémon in bodies of water.", effect = "Used to find Pokémon on the Good Rod list for an area, which are generally mediocre." },
  { id = "SUPERROD", n = 424, slug = "super-rod", name = "Super Rod", category = "gameplay", shortEffect = "Used to catch Pokémon in bodies of water.", effect = "Used to find Pokémon on the Super Rod list for an area, which are generally the best available there." },
