  { id = "LUNARWING", n = 430, slug = "lunar-wing", name = "Lunar Wing", category = "event-items", shortEffect = "Cures sailor’s son of nightmares in Canalave City.", effect = "Cures the sailor’s son of his nightmares; no reward, only a side effect of seeing Cresselia." },
  { id = "MEMBERCARD", n = 431, slug = "member-card", name = "Member Card", category = "event-items", shortEffect = "Allows access to Newmoon Island and Darkrai.", effect = "Provides access to Newmoon Island and Darkrai." },
  { id = "AZUREFLUTE", n = 432, slug = "azure-flute", name = "Azure Flute", category = "event-items", shortEffect = "Allows entry into the Hall of Origin. Unreleased." },
  { id = "SSTICKET", n = 433, slug = "ss-ticket", name = "S.S. Ticket", category = "plot-advancement", shortEffect = "Ticket for a ship. (RSE: S.S. Tidal LF: S.S. Anne HG: S.S. Aqua)", effect = "Allows passage on a ferry. The same item is used for different ferries between different games." },
