  { id = "PARCEL", n = 436, slug = "parcel", name = "Parcel", category = "plot-advancement", shortEffect = "Given to the trainer’s rival in Jubilife City. Contains Town Maps.", effect = "Given to the trainer’s rival in Jubilife City. Contains two Town Maps, one of which is given to the trainer upon delivery." },
  { id = "COUPON1", n = 437, slug = "coupon-1", name = "Coupon 1", category = "plot-advancement", shortEffect = "The first of three tickets used to obtain a Pokétch.", effect = "One of three coupons needed to receive a Pokétch." },
  { id = "COUPON2", n = 438, slug = "coupon-2", name = "Coupon 2", category = "plot-advancement", shortEffect = "The second of three tickets used to obtain a Pokétch.", effect = "One of three coupons needed to receive a Pokétch." },
  { id = "COUPON3", n = 439, slug = "coupon-3", name = "Coupon 3", category = "plot-advancement", shortEffect = "The last of three tickets used to obtain a Pokétch.", effect = "One of three coupons needed to receive a Pokétch." },
  { id = "STORAGEKEY", n = 440, slug = "storage-key", name = "Storage Key", category = "plot-advancement", shortEffect = "Grants access to the Team Galactic warehouse in Veilstone City." },
  { id = "SECRETPOTION", n = 441, slug = "secret-potion", name = "Secret Potion", category = "plot-advancement", shortEffect = "Used to heal the Ampharos at the top of Olivine Lighthouse.", effect = "Required to cure the Psyducks blocking Route 210 of their chronic headaches." },
  { id = "GRISEOUSORB", n = 442, slug = "griseous-orb", name = "Griseous Orb", category = "species-specific", flingPower = 60, shortEffect = "Boosts the damage from Giratina’s Dragon-type and Ghost-type moves by 20%, and transforms it into Origin Forme.", effect = "Held by Giratina : Holder’s Dragon and Ghost moves have 1.2× their base power. Holder is in Origin Forme. This item cannot be held by any Pokémon but Giratina. When you enter the Union Room or connect to Wi-Fi, this item returns to your bag." },
  { id = "VSRECORDER", n = 443, slug = "vs-recorder", name = "Vs. Recorder", category = "gameplay", shortEffect = "Records wireless, Wi-Fi, or Battle Frontier battles, and stores points.", effect = "Optionally records wireless, Wi-Fi, and Battle Frontier battles. Tracks Battle Points earned in the Battle Frontier, and stores commemorative prints." },
  { id = "GRACIDEA", n = 444, slug = "gracidea", name = "Gracidea", category = "event-items", shortEffect = "Changes an unfrozen Shaymin to Sky Forme in the day.", effect = "Used by trainer on a Shaymin : Changes the target Shaymin from Land Forme to Sky Forme. This item cannot be used on a frozen Shaymin or at night. Sky Forme Shaymin will revert to Land Forme overnight, when frozen, and upon entering a link battle. This item must be used again to change it back." },
  { id = "SECRETKEY", n = 445, slug = "secret-key", name = "Secret Key", category = "event-items", shortEffect = "Gen IV: The key to Rotom’s appliance room. Gen III: The key to Cinnabar Gym.", effect = "Used by trainer in the Galactic Eterna Building, on the ground floor, to the left of the TV : Unlocks the secret Rotom room, in which there are five appliances which can change Rotom’s form." },
  { id = "APRICORNBOX", n = 446, slug = "apricorn-box", name = "Apricorn Box", category = "gameplay", shortEffect = "Holds Apricorns.", effect = "Stores Apricorns." },
  { id = "BERRYPOTS", n = 447, slug = "berry-pots", name = "Berry Pots", category = "gameplay", shortEffect = "Allows portable berry growing.", effect = "Contains four portable pots of soil suitable for growing berries." },
  { id = "SQUIRTBOTTLE", n = 448, slug = "squirt-bottle", name = "Squirt Bottle", category = "plot-advancement", shortEffect = "Use on Sudowoodo blocking the path on Route 36. Also waters berries.", effect = "Required to water berries within the Berry Pots. Required to battle the Sudowoodo on Route 36. This item cannot be directly used from the bag." },
  { id = "LUREBALL", n = 449, slug = "lure-ball", name = "Lure Ball", category = "apricorn-balls", shortEffect = "3× effectiveness while fishing. Made from Blu Apricorn.", effect = "Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon was encountered by fishing, the wild Pokémon’s catch rate is 3× normal." },
  { id = "LEVELBALL", n = 450, slug = "level-ball", name = "Level Ball", category = "apricorn-balls", shortEffect = "Success rate based off of fraction target Pokémon is of user’s Pokémon. Made from Red Apricorn.", effect = "Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the trainer’s Pokémon’s level is higher than: * four times the wild Pokémon’s, the wild Pokémon’s catch rate is 8× normal. * than twice the wild Pokémon’s, the wild Pokémon’s catch rate is 4× normal. * the wild Pokémon’s, the wild Pokémon’s catch rate is 2× normal." },
  { id = "MOONBALL", n = 451, slug = "moon-ball", name = "Moon Ball", category = "apricorn-balls", shortEffect = "4× effectiveness on familes of Pokémon with a Moon Stone evolution. Made from Ylw Apricorn.", effect = "Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon is a Clefairy, Nidoran♂, Nidoran♀, Jigglypuff, Skitty, or any evolution thereof, the wild Pokémon has 4× its catch rate." },
  { id = "HEAVYBALL", n = 452, slug = "heavy-ball", name = "Heavy Ball", category = "apricorn-balls", shortEffect = "Has flat bonus or penalty to catch rate depending on weight class of target. Made from Blk Apricorn.", effect = "Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon weighs: * 409.6 kg (903.0 lb) or more, its catch rate is 40 more than normal. * 307.2 kg (677.3 lb) or more, its catch rate is 30 more than normal. * 204.8 kg (451.5 lb) or more, its catch rate is 20 more than normal. * less than 204.8 kg (451.5 lb), its catch rate is 20 less than normal." },
  { id = "FASTBALL", n = 453, slug = "fast-ball", name = "Fast Ball", category = "apricorn-balls", shortEffect = "4× effectiveness on Pokémon with 100 or greater base speed. (Gen II: Roaming or Fleeing Pokémon). Made from Wht Apricorn.", effect = "Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. : If the wild Pokémon’s base speed is 100 or more, its catch rate is 4× normal." },
  { id = "FRIENDBALL", n = 454, slug = "friend-ball", name = "Friend Ball", category = "apricorn-balls", shortEffect = "Caught Pokémon start with 200 happiness. Made from Grn Apricorn.", effect = "Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If caught, the wild Pokémon’s happiness starts at 200." },
  { id = "LOVEBALL", n = 455, slug = "love-ball", name = "Love Ball", category = "apricorn-balls", shortEffect = "8× effectiveness on opposite sex, same species targets of the Active Pokémon. Made from Pnk Apricorn.", effect = "Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the trainer’s Pokémon and wild Pokémon are of the same species but opposite genders, the wild Pokémon’s catch rate is 8× normal." },
  { id = "PARKBALL", n = 456, slug = "park-ball", name = "Park Ball", category = "standard-balls", shortEffect = "Catches Pokémon in the Pal Park every time.", effect = "Used by a trainer in battle : Catches a wild Pokémon. This item can only be used in Pal Park." },
  { id = "SPORTBALL", n = 457, slug = "sport-ball", name = "Sport Ball", category = "standard-balls", shortEffect = "Tries to catch a Pokémon in the Bug-Catching contest in National Park. (Gen II: Park Ball)", effect = "Used by a trainer in battle : Attempts to catch a wild Pokémon. The wild Pokémon’s catch rate is 1.5× normal." },
  { id = "REDAPRICORN", n = 458, slug = "red-apricorn", name = "Red Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Level Ball.", effect = "May be given to Kurt in Azalea Town to produce a Level Ball." },
  { id = "BLUEAPRICORN", n = 459, slug = "blue-apricorn", name = "Blue Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Lure Ball.", effect = "May be given to Kurt in Azalea Town to produce a Lure Ball." },
  { id = "YELLOWAPRICORN", n = 460, slug = "yellow-apricorn", name = "Yellow Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Moon Ball.", effect = "May be given to Kurt in Azalea Town to produce a Moon Ball." },
  { id = "GREENAPRICORN", n = 461, slug = "green-apricorn", name = "Green Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Friend Ball.", effect = "May be given to Kurt in Azalea Town to produce a Friend Ball." },
  { id = "PINKAPRICORN", n = 462, slug = "pink-apricorn", name = "Pink Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Love Ball.", effect = "May be given to Kurt in Azalea Town to produce a Love Ball." },
