  { id = "BLACKAPRICORN", n = 464, slug = "black-apricorn", name = "Black Apricorn", category = "apricorn-box", flingPower = 10, shortEffect = "Used to make a Heavy Ball.", effect = "May be given to Kurt in Azalea Town to produce a Heavy Ball." },
  { id = "DOWSINGMACHINE", n = 465, slug = "dowsing-machine", name = "Dowsing Machine", category = "gameplay", shortEffect = "Use to find hidden items on the field. AKA Itemfinder.", effect = "Used by trainer outside of battle : Searches for hidden items." },
