  { id = "ENIGMASTONE", n = 470, slug = "enigma-stone", name = "Enigma Stone", category = "event-items", shortEffect = "S: Summons Latias H: Summons Latios.", effect = "When taken to the Pewter City museum, causes Latias or Latios to attack the trainer. The Pokémon to appear will be whicher can’t be encountered roaming in the wild." },
